package com.estradaplay.comunista;
import android.content.*;import android.graphics.*;import android.net.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.ComponentActivity;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public final class NearbyServicesActivity extends ComponentActivity{private LinearLayout page,results;private double lat=Double.NaN,lon=Double.NaN;private boolean reg;private BroadcastReceiver rx;private final int TEXT=Color.rgb(246,238,224),MUTED=Color.rgb(174,151,146),RED=Color.rgb(190,18,38);@Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView sv=new ScrollView(this);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(18),dp(18),dp(18),dp(28));page.setBackgroundColor(Color.rgb(9,5,7));sv.addView(page);setContentView(sv);page.addView(t("SERVIÇOS NA ESTRADA",27,TEXT,true));page.addView(t("Busca online em até 15 km. Favoritos ficam salvos no aparelho.",12,MUTED,false));Button fav=new Button(this);fav.setText("MEUS FAVORITOS");fav.setOnClickListener(v->startActivity(new Intent(this,RoadFavoritesActivity.class)));page.addView(fav,new LinearLayout.LayoutParams(-1,dp(50)));LinearLayout a=row();addButton(a,"POSTOS","fuel");addButton(a,"HOSPITAIS","hospital");page.addView(a);LinearLayout c=row();addButton(c,"OFICINAS","car_repair");addButton(c,"RESTAURANTES","restaurant");page.addView(c);results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);page.addView(results);}private void addButton(LinearLayout r,String label,String type){Button b=new Button(this);b.setText(label);b.setOnClickListener(v->search(type));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(52),1);p.setMargins(dp(3),dp(6),dp(3),0);r.addView(b,p);}private void search(String type){if(DriveSettings.offlineTestMode(this)){toast("Busca de serviços bloqueada no teste offline.");return;}if(!Double.isFinite(lat)||!Double.isFinite(lon)){toast("Aguardando posição GPS.");return;}results.removeAllViews();results.addView(t("BUSCANDO...",14,RED,true));new Thread(()->{ArrayList<Item> items=query(type);runOnUiThread(()->show(items));},"epc-nearby").start();}private ArrayList<Item> query(String type){ArrayList<Item> out=new ArrayList<>();try{String selector;if("fuel".equals(type))selector="[amenity=fuel]";else if("hospital".equals(type))selector="[amenity=hospital]";else if("restaurant".equals(type))selector="[amenity=restaurant]";else selector="[shop=car_repair]";String q=String.format(Locale.US,"[out:json][timeout:25];(node(around:15000,%.6f,%.6f)%s;way(around:15000,%.6f,%.6f)%s;);out center tags 30;",lat,lon,selector,lat,lon,selector);HttpURLConnection h=(HttpURLConnection)new URL("https://overpass-api.de/api/interpreter?data="+URLEncoder.encode(q,"UTF-8")).openConnection();h.setConnectTimeout(12000);h.setReadTimeout(35000);h.setRequestProperty("User-Agent","EstradaPlayComunista/1.6 Android");try(InputStream in=h.getInputStream();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[16384];int n;while((n=in.read(buf))>0&&b.size()<4000000)b.write(buf,0,n);JSONObject root=new JSONObject(new String(b.toByteArray(),StandardCharsets.UTF_8));JSONArray e=root.optJSONArray("elements");if(e!=null)for(int i=0;i<e.length();i++){JSONObject x=e.optJSONObject(i);if(x==null)continue;double la=x.optDouble("lat",Double.NaN),lo=x.optDouble("lon",Double.NaN);JSONObject center=x.optJSONObject("center");if(!Double.isFinite(la)&&center!=null){la=center.optDouble("lat",Double.NaN);lo=center.optDouble("lon",Double.NaN);}if(!Double.isFinite(la)||!Double.isFinite(lo))continue;JSONObject tags=x.optJSONObject("tags");String name=tags==null?"":tags.optString("name","");if(name.isEmpty())name=label(type);out.add(new Item(name,type,la,lo,distance(lat,lon,la,lo)));}}out.sort(Comparator.comparingDouble(a->a.d));if(out.size()>15)return new ArrayList<>(out.subList(0,15));}catch(Throwable ignored){}return out;}private void show(ArrayList<Item> items){results.removeAllViews();if(items.isEmpty()){results.addView(t("Nenhum resultado encontrado agora.",14,MUTED,false));return;}for(Item x:items){LinearLayout r=row();Button go=new Button(this);go.setAllCaps(false);go.setText(x.name+"\n"+(x.d>=1000?String.format(Locale.getDefault(),"%.1f km",x.d/1000):Math.round(x.d)+" m"));go.setOnClickListener(v->{DestinationStore.save(this,new DestinationStore.Destination(x.name,x.lat,x.lon));startActivity(new Intent(this,RoadMapActivity.class));});Button save=new Button(this);save.setText("★");save.setOnClickListener(v->{FavoriteRoadStore.add(this,new FavoriteRoadStore.Item(x.name,label(x.type),x.lat,x.lon));toast("Salvo nos favoritos");});r.addView(go,new LinearLayout.LayoutParams(0,dp(68),1));r.addView(save,new LinearLayout.LayoutParams(dp(62),dp(68)));results.addView(r);}}@Override protected void onStart(){super.onStart();rx=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){lat=i.getDoubleExtra("lat",Double.NaN);lon=i.getDoubleExtra("lon",Double.NaN);}};IntentFilter f=new IntentFilter(RoadSafetyService.ACTION_STATE);if(Build.VERSION.SDK_INT>=33)registerReceiver(rx,f,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(rx,f);reg=true;}@Override protected void onStop(){if(reg)try{unregisterReceiver(rx);}catch(Throwable ignored){}reg=false;super.onStop();}private String label(String t){if("fuel".equals(t))return"Posto";if("hospital".equals(t))return"Hospital";if("restaurant".equals(t))return"Restaurante";return"Oficina";}private static double distance(double a,double b,double c,double d){double R=6371000,p1=Math.toRadians(a),p2=Math.toRadians(c),dp=Math.toRadians(c-a),dl=Math.toRadians(d-b);double x=Math.sin(dp/2)*Math.sin(dp/2)+Math.cos(p1)*Math.cos(p2)*Math.sin(dl/2)*Math.sin(dl/2);return R*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);return l;}private TextView t(String v,float s,int c,boolean b){TextView t=new TextView(this);t.setText(v);t.setTextSize(s);t.setTextColor(c);if(b)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private void toast(String v){Toast.makeText(this,v,Toast.LENGTH_SHORT).show();}private int dp(float v){return Math.round(v*getResources().getDisplayMetrics().density);}private static final class Item{final String name,type;final double lat,lon,d;Item(String n,String t,double a,double b,double d){name=n;type=t;lat=a;lon=b;this.d=d;}}}
